import sys
from bisect import bisect_left


def main() -> None:
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    m = int(data[1])
    a = data[2:2 + n]
    b = data[2 + n:2 + n + m]
    spots = {}
    for j in range(m - 1, -1, -1):
        v = b[j]
        lst = spots.get(v)
        if lst is None:
            spots[v] = [j]
        else:
            lst.append(j)
    tails = []
    push = tails.append
    for v in a:
        lst = spots.get(v)
        if lst is None:
            continue
        for j in lst:
            t = bisect_left(tails, j)
            if t == len(tails):
                push(j)
            else:
                tails[t] = j
    print(n + m - 2 * len(tails))


main()
